define(["jquery"],function($){function isFullscreenActive(){return!!(document.fullscreenElement||document.webkitFullscreenElement||document.mozFullScreenElement||document.msFullscreenElement)}function requestFullscreen(){var element=document.documentElement;var fn=element.requestFullscreen||element.webkitRequestFullscreen||element.mozRequestFullScreen||element.msRequestFullscreen;if(!fn){return false}try{fn.call(element);return true}catch(e){return false}}function showMessage(cfg){$("#proctoringpolicy_fullscreen-message").show()}function hideMessage(cfg){$("#proctoringpolicy_fullscreen-message").hide()}function warnStatus(cfg,text){$("#status-danger").show().html(text)}function emitLog(ctx,action,value){$(document).trigger("local_kopere_proctoring:policy_log",[{cmid:ctx.cmid,attemptid:ctx.attemptid,policy:"fullscreen",action:action,value:value||""}])}function bindFullscreenExit(ctx,cfg,state){$(document).on("fullscreenchange webkitfullscreenchange mozfullscreenchange MSFullscreenChange",function(){if(!state.inexam){return}if(!isFullscreenActive()){state.exits=state.exits+1;emitLog(ctx,"fullscreen_exit",String(state.exits));showMessage(cfg);if(state.exits>state.limit){warnStatus(cfg,"Fullscreen limit exceeded.");emitLog(ctx,"fullscreen_blocked","limit")}}})}function gateStart(ctx,cfg,state){var startsel="#start-exam,#return-exam-1";$(document).on("click",startsel,function(e){if(isFullscreenActive()){hideMessage(cfg);state.inexam=true;return}var ok=requestFullscreen();if(!ok){e.preventDefault();e.stopPropagation();showMessage(cfg);warnStatus(cfg,"Your browser does not support fullscreen.");emitLog(ctx,"fullscreen_not_supported","");return}e.preventDefault();e.stopPropagation();var start=Date.now();var t=setInterval(function(){if(isFullscreenActive()){clearInterval(t);hideMessage(cfg);state.inexam=true;emitLog(ctx,"fullscreen_entered","");$(document).trigger("local_kopere_proctoring:fullscreen_ready");return}if(Date.now()-start>3e3){clearInterval(t);showMessage(cfg);emitLog(ctx,"fullscreen_failed","")}},100)})}return{init:function(ctx,cfg){var state={inexam:false,exits:0,limit:Number(cfg.limit||2)};bindFullscreenExit(ctx,cfg,state);gateStart(ctx,cfg,state);emitLog(ctx,"fullscreen_policy_loaded","")}}});